#!/usr/bin/env python3
from pathlib import Path

ENCODED = ""
assert len(ENCODED) == 210 * 13
rows = [list(map(int, ENCODED[i:i+13])) for i in range(0, len(ENCODED), 13)]
row_text = ",\n".join("  [" + ", ".join(map(str, row)) + "]" for row in rows)
PRELUDE = 'import Mathlib\n/-!\n# Compact finite Fano forcing table\n\nThe 210 rows encode\n`pairA,pairB,triple0,triple1,triple2,i,j,k,edge1,edge2,apex,a,b`.\nThe finite validity and completeness claims are checked by `native_decide`.\n-/\n\nnamespace FanoLowerBound\n\nstructure RadonConfig where\n  pairA : Nat\n  pairB : Nat\n  triple0 : Nat\n  triple1 : Nat\n  triple2 : Nat\n  deriving DecidableEq, Repr\n\nstructure FanoForcingCert extends RadonConfig where\n  i : Nat\n  j : Nat\n  k : Nat\n  edge1 : Nat\n  edge2 : Nat\n  apex : Nat\n  a : Nat\n  b : Nat\n  deriving DecidableEq, Repr\n\ndef fanoLine : Nat → List Nat\n  | 0 => [1, 2, 3]\n  | 1 => [1, 4, 5]\n  | 2 => [1, 6, 7]\n  | 3 => [2, 4, 6]\n  | 4 => [2, 5, 7]\n  | 5 => [3, 4, 7]\n  | 6 => [3, 5, 6]\n  | _ => []\n\ndef hasPoint (line point : Nat) : Bool := (fanoLine line).contains point\n\ndef lineContains3 (a b c : Nat) : Bool :=\n  (List.range 7).any fun line =>\n    hasPoint line a && hasPoint line b && hasPoint line c\n\ndef sameTripleSet (a b c x y z : Nat) : Bool :=\n  ([a, b, c].all fun t => [x, y, z].contains t) &&\n    ([x, y, z].all fun t => [a, b, c].contains t)\n\ndef FanoForcingCert.valid (c : FanoForcingCert) : Bool :=\n  decide (c.pairA < c.pairB) &&\n  decide (c.triple0 < c.triple1 ∧ c.triple1 < c.triple2) &&\n  decide (c.pairB < 7 ∧ c.triple2 < 7) &&\n  decide (c.triple0 ≠ c.pairA ∧ c.triple0 ≠ c.pairB ∧\n    c.triple1 ≠ c.pairA ∧ c.triple1 ≠ c.pairB ∧\n    c.triple2 ≠ c.pairA ∧ c.triple2 ≠ c.pairB) &&\n  hasPoint c.pairA c.i && hasPoint c.pairB c.i &&\n  lineContains3 c.i c.j c.k &&\n  sameTripleSet c.edge1 c.edge2 c.apex c.triple0 c.triple1 c.triple2 &&\n  hasPoint c.edge1 c.j && hasPoint c.edge2 c.j && hasPoint c.apex c.k &&\n  hasPoint c.pairA c.a && decide (c.a ≠ c.i) &&\n  hasPoint c.pairB c.b && decide (c.b ≠ c.i) &&\n  decide ([c.i, c.j, c.k, c.a, c.b].Nodup) &&\n  lineContains3 c.a c.b c.k\n\ndef allRadonConfigs : List RadonConfig :=\n  (List.range 7).flatMap fun A =>\n    (List.range 7).flatMap fun B =>\n      (List.range 7).flatMap fun x =>\n        (List.range 7).flatMap fun y =>\n          (List.range 7).flatMap fun z =>\n            if A < B ∧ x < y ∧ y < z ∧\n                x ≠ A ∧ x ≠ B ∧ y ≠ A ∧ y ≠ B ∧ z ≠ A ∧ z ≠ B then\n              [{ pairA := A, pairB := B, triple0 := x, triple1 := y, triple2 := z }]\n            else []\n\nprivate def certOfRow : List Nat → FanoForcingCert\n  | [A, B, x, y, z, i, j, k, e1, e2, apex, a, b] =>\n      { pairA := A, pairB := B, triple0 := x, triple1 := y, triple2 := z,\n        i := i, j := j, k := k, edge1 := e1, edge2 := e2, apex := apex,\n        a := a, b := b }\n  | _ =>\n      { pairA := 0, pairB := 0, triple0 := 0, triple1 := 0, triple2 := 0,\n        i := 0, j := 0, k := 0, edge1 := 0, edge2 := 0, apex := 0,\n        a := 0, b := 0 }\n\n'
ROW_START = 'private def fanoForcingRows : List (List Nat) := [\n'
SUFFIX = '\n]\n\ndef fanoForcingCertificates : List FanoForcingCert :=\n  fanoForcingRows.map certOfRow\n\ntheorem fano_forcing_certificate_count : fanoForcingCertificates.length = 210 := by\n  native_decide\n\ntheorem all_fano_forcing_certificates_valid :\n    fanoForcingCertificates.all FanoForcingCert.valid = true := by\n  native_decide\n\ntheorem fano_forcing_table_complete :\n    (fanoForcingCertificates.map FanoForcingCert.toRadonConfig).toFinset =\n      allRadonConfigs.toFinset := by\n  native_decide\n\ntheorem all_radon_config_count : allRadonConfigs.toFinset.card = 210 := by\n  native_decide\n\n#print axioms FanoLowerBound.all_fano_forcing_certificates_valid\n#print axioms FanoLowerBound.fano_forcing_table_complete\n\nend FanoLowerBound\n'
out = Path(__file__).resolve().parent / "FanoLowerBound" / "FanoForcingTable.lean"
out.write_text(PRELUDE + ROW_START + row_text + SUFFIX, encoding="utf-8")
print(f"generated {out} with {len(rows)} rows")
